import json
from datetime import datetime, timezone, timedelta

d = json.load(open('/Users/ktoclaw/.hermes/cron/jobs.json'))
now = datetime.now(timezone(timedelta(hours=8)))
print('=== Past-due one-shot jobs ===')
for job in d.get('jobs', []):
    if job.get('kind') == 'once' and job.get('run_at'):
        run_at = datetime.fromisoformat(job['run_at'].replace('Z', '+00:00'))
        # Convert to GMT+8 for comparison
        run_at_local = run_at.astimezone(timezone(timedelta(hours=8)))
        if run_at_local < now:
            print(f\"  OVERDUE: {job['name']} (ran at {job['run_at']})\")
        else:
            print(f\"  Future: {job['name']} (runs at {job['run_at']})\")
" 2>/dev/null"}

